/bin/bash -c "python - <<'PY'
import numpy as np, cv2
z=np.load('source_pixels.npz')['rgb'].astype(float)
# hand ROIs broad trajectories
rois={'blue':(125,180,48,85),'red':(92,153,60,92),'puck':(55,120,72,105)}
for f in range(0,96,2):
 im=z[f]
 vals=[]
 for name,(x0,x1,y0,y1) in rois.items():
  p=im[y0:y1,x0:x1]
  if name=='blue': score=p[:,:,2]-p[:,:,0]
  elif name=='red': score=p[:,:,0]-(p[:,:,1]+p[:,:,2])/2
  else:
   # brightness over local bg, only high sat low
   score=p.mean(2)-190
  yy,xx=np.mgrid[y0:y1,x0:x1]
  m=score> (20 if name=='blue' else 25 if name=='red' else 20)
  if name=='blue': m &= (p[:,:,2]-p[:,:,1]>4)&(p[:,:,0]>60)
  if name=='red': m &= (p[:,:,0]-p[:,:,1]>35)&(p[:,:,0]-p[:,:,2]>20)
  if name=='puck': m &= (p.max(2)-p.min(2)<30)
  if m.sum():
   vals.append(f'{name}:{xx[m].mean():.1f},{yy[m].mean():.1f},n{m.sum()}')
  else: vals.append(f'{name}:none')
 print(f, ' '.join(vals))
PY"

/bin/bash -c "python - <<'PY'
import numpy as np, cv2
z=np.load('source_pixels.npz')['rgb'].astype(np.float32)
# inspect contours of saturated objects at stable frames using fixed color thresholds
for f in [0,14,20,30,40,60,95]:
 im=z[f]
 print('\\nframe',f)
 for name,m in [('blue',(im[:,:,2]-im[:,:,0]>45)&(im[:,:,2]-im[:,:,1]>10)&(im[:,:,0]>50)),('red',(im[:,:,0]-im[:,:,1]>55)&(im[:,:,0]-im[:,:,2]>30)&(im[:,:,1]<180))]:
  # restrict relevant bbox
  if name=='blue': m &= (np.indices(m.shape)[1]>125)&(np.indices(m.shape)[1]<180)&(np.indices(m.shape)[0]>45)&(np.indices(m.shape)[0]<85)
  else: m &= (np.indices(m.shape)[1]>90)&(np.indices(m.shape)[1]<155)&(np.indices(m.shape)[0]>55)&(np.indices(m.shape)[0]<95)
  n,lab,stats,cents=cv2.connectedComponentsWithStats(m.astype(np.uint8),8)
  for i in range(1,n):
   if stats[i,4]>=8: print(name,tuple(stats[i]),tuple(np.round(cents[i],2)))
PY"
